BMI = น้ำหนัก (กก.) ÷ ส่วนสูง (เมตร)² ต้องแปลงส่วนสูงจากเซนติเมตรเป็นเมตรก่อน เกณฑ์ด้านล่างใช้ของคนเอเชีย

```python
def bmi_category(weight_kg: float, height_cm: float) -> tuple[float, str]:
    """คืนค่า BMI (ปัดทศนิยม 1 ตำแหน่ง) และเกณฑ์"""
    height_m = height_cm / 100
    bmi = weight_kg / (height_m ** 2)
    if bmi < 18.5:
        label = "น้ำหนักน้อย"
    elif bmi < 23:
        label = "ปกติ"
    elif bmi < 25:
        label = "ท้วม"
    elif bmi < 30:
        label = "อ้วน"
    else:
        label = "อ้วนมาก"
    return round(bmi, 1), label

print(bmi_category(60, 165))  # (22.0, 'ปกติ')
```
